-- 20260731c_curzon_ar_payment_import.sql
--
-- ONE-OFF DATA IMPORT. Run once, after 20260731_alvys_invoice_backfill.
--
-- Curzon tracked payments in the old my-calendar AR system until it
-- stopped being used around May. That history is still in the retired
-- Supabase project (vgglyebsbbgooqmguzmi) and covers real payments that
-- FleetCal has no record of — every one of those invoices is currently
-- sitting in Receivables as open money.
--
-- 1,011 invoices there are paid/matched. 963 join to a FleetCal invoice
-- on loads.load_num, and the join is trustworthy: the invoiced amount
-- agrees to the cent on ALL 963, with zero drift. 48 don't match any
-- load in FleetCal (they predate the import window) and are skipped —
-- listed at the bottom of this comment.
--
--   allocations   963   $751,126.75
--     with proof  336   (95 proofs: 38 bank deposits, 57 remittances)
--     unbacked    627   (marked paid by hand over there; no evidence
--                        exists to import, and inventing one would be
--                        worse than showing the gap)
--   payment dates 2026-03-18 .. 2026-05-12
--
-- AMOUNTS: each allocation settles the FleetCal invoice total, NOT the
-- old system's paid_amount. That is deliberate. Only 341 rows carry a
-- paid_amount, and 110 of those disagree with the invoiced amount —
-- but 18 of the disagreements swing more than 20% and account for
-- +$36,315 of the +$37,432 total variance. Those are artifacts of the
-- old system's proration defect, which split a deposit across invoices
-- by size (a $150 invoice recorded as $3,675 paid). The other 80 are
-- ~1% shortfalls that look like genuine quick-pay discounts and total
-- just -$378. Importing the invoice total loses that $378 of quick-pay
-- detail; importing paid_amount would have introduced $36,315 of money
-- that never existed. The $378 is the better error.
--
-- Proofs are tagged source='api' with external_id 'mycal_dep_<uuid>' /
-- 'mycal_rem_<uuid>', so re-running is a no-op and the origin of every
-- record stays legible.
--
-- REVERSAL:
--   DELETE FROM invoice_payments WHERE created_by = 'system:curzon-ar-import';
--   DELETE FROM payment_proofs   WHERE external_id LIKE 'mycal_%';
--   -- then re-open anything this closed:
--   UPDATE invoices SET status='sent', paid_at=NULL, paid_amount=NULL, paid_method=NULL
--   WHERE org_id='org_3Ck09w6LuEjiX4WgxJEPyiyjuXN' AND status='paid'
--     AND NOT EXISTS (SELECT 1 FROM invoice_payments p WHERE p.invoice_id = invoices.id);

BEGIN;

-- ── Evidence ──────────────────────────────────────────────────────

CREATE TEMP TABLE _proof_in (
  external_id text, kind text, occurred_on date, amount numeric(12,2),
  payer_raw text, reference text, note text
) ON COMMIT DROP;

;

  org_id, kind, source, payer_raw, occurred_on, amount, reference, note, external_id, created_by
)
SELECT
  'org_3Ck09w6LuEjiX4WgxJEPyiyjuXN', p.kind, 'api', p.payer_raw,
  p.occurred_on, p.amount, p.reference, p.note, p.external_id,
  'system:curzon-ar-import'
FROM _proof_in p
WHERE NOT EXISTS (
  SELECT 1 FROM payment_proofs x
  WHERE x.org_id = 'org_3Ck09w6LuEjiX4WgxJEPyiyjuXN'
    AND x.source = 'api' AND x.external_id = p.external_id
);

-- ── Allocations ───────────────────────────────────────────────────

CREATE TEMP TABLE _alloc_in (
  invoice_id uuid, amount numeric(12,2), paid_on date, proof_external_id text
) ON COMMIT DROP;

;

  org_id, invoice_id, proof_id, amount, paid_on, method, note, created_by
)
SELECT
  'org_3Ck09w6LuEjiX4WgxJEPyiyjuXN',
  a.invoice_id,
  pp.id,
  a.amount,
  a.paid_on,
  NULL,
  'Imported from the Curzon AR system',
  'system:curzon-ar-import'
FROM _alloc_in a
LEFT JOIN payment_proofs pp
  ON pp.org_id = 'org_3Ck09w6LuEjiX4WgxJEPyiyjuXN'
 AND pp.source = 'api'
 AND pp.external_id = a.proof_external_id
-- Never compete with a payment already recorded, whether by the earlier
-- backfill or by hand in the app.
WHERE NOT EXISTS (
  SELECT 1 FROM invoice_payments p WHERE p.invoice_id = a.invoice_id
);

-- ── Mirror onto the invoice summary ───────────────────────────────
-- Exactly what recomputeInvoicePaid() would derive, so the first later
-- recompute is a no-op: paid_at = paid_on at 12:00Z, method NULL.

UPDATE invoices i
SET status      = 'paid',
    paid_amount = p.amount,
    paid_at     = ((p.paid_on::text || 'T12:00:00Z')::timestamptz),
    paid_method = NULL
FROM invoice_payments p
WHERE p.invoice_id = i.id
  AND p.created_by = 'system:curzon-ar-import'
  AND i.status <> 'void';

-- Loads follow the invoice, so the closeout queue and Billing agree.
UPDATE loads l
SET billing_status = 'paid'
FROM invoices i
JOIN invoice_payments p ON p.invoice_id = i.id AND p.created_by = 'system:curzon-ar-import'
WHERE l.id = i.load_id
  AND l.org_id = 'org_3Ck09w6LuEjiX4WgxJEPyiyjuXN'
  AND l.billing_status <> 'paid';

COMMIT;

-- Expect: proofs 95, allocations 963, $751,126.75, all dated
-- 2026-03-18..2026-05-12. AR open should fall $2,785,552 -> $2,034,426.
SELECT
  (SELECT count(*) FROM payment_proofs   WHERE created_by = 'system:curzon-ar-import') AS proofs_imported,
  (SELECT count(*) FROM invoice_payments WHERE created_by = 'system:curzon-ar-import') AS allocations_imported,
  (SELECT round(sum(amount)::numeric,2) FROM invoice_payments WHERE created_by = 'system:curzon-ar-import') AS amount_applied,
  (SELECT count(*) FROM invoice_payments WHERE created_by = 'system:curzon-ar-import' AND proof_id IS NOT NULL) AS with_proof,
  (SELECT min(paid_on) FROM invoice_payments WHERE created_by = 'system:curzon-ar-import') AS earliest_payment,
  (SELECT max(paid_on) FROM invoice_payments WHERE created_by = 'system:curzon-ar-import') AS latest_payment;
